// Meow Drop service worker: classic script (no importScripts), atomic versioned precache, cache-first.
// The block between the precache markers is generated by `npm run stamp` (tools/stamp-sw.mjs):
// never edit it by hand. A new VERSION is what makes installed apps pick up a release.
'use strict';

// <precache>
const VERSION = '841b6c47e5';
const ASSETS = [
  './',
  './css/style.css',
  './fonts/nunito-latin-800-normal.woff2',
  './fonts/nunito-latin-900-normal.woff2',
  './icons/apple-touch-icon.png',
  './icons/favicon-32.png',
  './icons/icon-192.png',
  './icons/icon-512.png',
  './icons/icon-maskable-512.png',
  './icons/icon.svg',
  './index.html',
  './manifest.webmanifest',
  './src/core/generator.js',
  './src/core/level-data.js',
  './src/core/levels.js',
  './src/core/progress.js',
  './src/core/rng.js',
  './src/core/rules.js',
  './src/core/shapes.js',
  './src/core/solver.js',
  './src/main.js',
  './src/platform/audio.js',
  './src/platform/device.js',
  './src/platform/haptics.js',
  './src/platform/pwa.js',
  './src/platform/storage.js',
  './src/ui/app.js',
  './src/ui/art.js',
  './src/ui/fx.js',
  './src/ui/layout.js',
  './src/ui/scene.js',
  './src/ui/slide.js',
];
// </precache>

// ninjacat1337.github.io is shared by every Pages project of the account: touch only our own caches.
const PREFIX = 'dropcat-';
const CACHE = PREFIX + VERSION;

self.addEventListener('install', (event) => {
  // cache: 'reload' bypasses the HTTP cache (GitHub Pages sends max-age=600), so a new version never
  // stores stale files. No skipWaiting() here: the page decides when to switch (SKIP_WAITING message).
  event.waitUntil(
    caches.open(CACHE).then((cache) => cache.addAll(ASSETS.map((u) => new Request(u, { cache: 'reload' }))))
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith(PREFIX) && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
});

// Safari rejects a navigation answered with a redirected response, so re-wrap one if it ever got cached.
function unredirect(res) {
  if (!res.redirected) return res;
  return res.blob().then((body) => new Response(body, { status: res.status, statusText: res.statusText, headers: res.headers }));
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET' || !req.url.startsWith(self.registration.scope)) return;
  if (req.cache === 'only-if-cached' && req.mode !== 'same-origin') return;

  // Lookups are by URL only: ignoreVary keeps a server's Vary header from causing an offline miss.
  if (req.mode === 'navigate') {
    // Single-page app: every in-scope navigation gets the cached shell.
    event.respondWith(
      caches.open(CACHE)
        .then((cache) => cache.match('./', { ignoreVary: true })
          .then((res) => res || cache.match('./index.html', { ignoreVary: true })))
        .then((res) => (res ? unredirect(res) : fetch(req)), () => fetch(req))
    );
    return;
  }

  event.respondWith(
    caches.open(CACHE)
      .then((cache) => cache.match(req, { ignoreSearch: true, ignoreVary: true }))
      .then((res) => res || fetch(req), () => fetch(req))
  );
});
